from pathlib import Path
import html
import json
import re

R = Path(__file__).resolve().parent
H = R.parent
data = json.loads((H / 'story-data.json').read_text())
by = {s['id']: s for s in data['screens']}
drafts = {lang: (H / f'draft-{lang}.md').read_text() for lang in ['ru', 'en']}
repairs = []

def plain(s):
    return html.unescape(re.sub(r'<[^>]+>', '', s.replace('</p>', '\n\n'))).strip()

def change(sid, lang, new):
    old = plain(by[sid]['copy'][lang]['body'])
    assert old != new and drafts[lang].count(old) == 1, (sid, lang)
    drafts[lang] = drafts[lang].replace(old, new, 1)
    repairs.append({'screen': sid, 'language': lang, 'old': old, 'new': new})

def replace(sid, lang, old, new):
    body = plain(by[sid]['copy'][lang]['body'])
    assert body.count(old) == 1, (sid, lang, old)
    change(sid, lang, body.replace(old, new, 1))

change('choice-3', 'ru', '\u0410\u0432\u0442\u043e\u0440 \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u0435\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0435 \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u044b \u0438 \u0441\u0430\u043c\u043e \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0432\u044b\u0431\u043e\u0440\u0430. \u041e\u043d \u043d\u0430\u0441\u0442\u0430\u0438\u0432\u0430\u0435\u0442: \u043c\u044b \u043d\u0435 \u0432\u0441\u0435\u0433\u0434\u0430 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u043c \u0442\u0435\u043c, \u043a\u0430\u043a\u0438\u0435 \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u044b \u043d\u0430\u043c \u0434\u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f, \u043d\u043e \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u043c \u043c\u0435\u0436\u0434\u0443 \u043d\u0438\u043c\u0438 \u0441\u0430\u043c\u0438. \u0412 \u0435\u0433\u043e \u0444\u0438\u043b\u043e\u0441\u043e\u0444\u0438\u0438 \u044d\u0442\u0443 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u044e\u044e \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f \u043e\u0442\u043d\u044f\u0442\u044c \u2014 \u043e \u043d\u0435\u0439 \u043c\u043e\u0436\u043d\u043e \u0437\u0430\u0431\u044b\u0442\u044c. \u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u043f\u0435\u0440\u0432\u044b\u0439 \u0448\u0430\u0433 \u043a \u044d\u0441\u0441\u0435\u043d\u0446\u0438\u0430\u043b\u0438\u0437\u043c\u0443 \u0434\u043b\u044f \u041c\u0430\u043a\u041a\u0435\u043e\u043d\u0430 \u0441\u043e\u0441\u0442\u043e\u0438\u0442 \u0432 \u0442\u043e\u043c, \u0447\u0442\u043e\u0431\u044b \u0432\u043d\u043e\u0432\u044c \u043f\u0440\u0438\u0437\u043d\u0430\u0442\u044c \u0437\u0430 \u0441\u043e\u0431\u043e\u0439 \u0432\u044b\u0431\u043e\u0440. \u0415\u0441\u043b\u0438 \u043a\u0430\u0436\u0434\u043e\u0435 \u043f\u043e\u0441\u0442\u0443\u043f\u0438\u0432\u0448\u0435\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0441\u0447\u0438\u0442\u0430\u0442\u044c \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u043c, \u043e\u0431\u0441\u0443\u0436\u0434\u0430\u0442\u044c \u043e\u0442\u0431\u043e\u0440 \u0443\u0436\u0435 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e: \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0441\u0438\u043b \u043e\u043a\u0430\u0436\u0435\u0442\u0441\u044f \u043e\u0442\u0434\u0430\u043d\u043e \u0447\u0443\u0436\u0438\u043c \u0440\u0435\u0448\u0435\u043d\u0438\u044f\u043c.')
change('choice-3', 'en', "The author distinguishes available alternatives from the act of choosing. He insists that, although we do not always control the alternatives available to us, choosing among them remains ours. In his philosophy, this inner capacity cannot be taken away; it can be forgotten. McKeown therefore places renewed recognition of one's power to choose at the beginning of Essentialism. If every incoming demand is treated as compulsory in advance, selection cannot even be discussed: the allocation of one's energy has already been handed over to other people's decisions.")
change('rest-2', 'ru', '\u041f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435 \u0432\u044b\u0445\u043e\u0434\u0438\u0442 \u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u044b \u043b\u0438\u0447\u043d\u043e\u0439 \u0441\u0438\u043b\u044b \u0432\u043e\u043b\u0438. \u0412 \u043a\u043d\u0438\u0433\u0435 \u043e\u0431\u0441\u0443\u0436\u0434\u0430\u044e\u0442\u0441\u044f \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438, \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u044e\u0449\u0438\u0435 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u043d\u043e\u0447\u043d\u043e\u0433\u043e \u043f\u0435\u0440\u0435\u043b\u0451\u0442\u0430 \u0438\u043b\u0438 \u043f\u043e\u0437\u0434\u043d\u0435\u0439 \u0440\u0430\u0431\u043e\u0442\u044b. \u0421\u0430\u043c \u041c\u0430\u043a\u041a\u0435\u043e\u043d \u043f\u0440\u043e\u0431\u0443\u0435\u0442 \u0441\u043f\u0430\u043b\u044c\u043d\u0443\u044e \u043a\u0430\u043f\u0441\u0443\u043b\u0443 \u0432 Google \u0438 \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u0435\u0442 \u0441\u0435\u0431\u044f \u043f\u043e\u0441\u043b\u0435 \u043d\u0435\u0451 \u043e\u0442\u0434\u043e\u0445\u043d\u0443\u0432\u0448\u0438\u043c. \u0427\u0438\u0441\u043b\u043e \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u0439 \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0433\u043e\u0440\u0430\u0437\u0434\u043e \u043c\u0435\u043d\u044c\u0448\u0435 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e\u0433\u043e. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u0430\u0432\u0442\u043e\u0440 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0441\u0430\u043c\u043e \u043d\u0430\u043b\u0438\u0447\u0438\u0435 \u043a\u0430\u043f\u0441\u0443\u043b\u044b \u0441\u0438\u0433\u043d\u0430\u043b\u043e\u043c: \u0441\u043e\u043d \u0437\u0430\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u0435\u0442 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u0430. \u0417\u0430\u0449\u0438\u0449\u0430\u0442\u044c \u0440\u0435\u0441\u0443\u0440\u0441 \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 \u0438 \u0432\u044b\u0434\u0435\u043b\u044f\u0442\u044c \u0432\u0440\u0435\u043c\u044f, \u0438 \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c \u043f\u0440\u0430\u0432\u0438\u043b\u0430, \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044e\u0449\u0438\u0435 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435. \u0413\u043b\u0430\u0432\u043d\u044b\u043c \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u043e\u043c \u0434\u043b\u044f \u043d\u0435\u0433\u043e \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c \u0440\u0430\u0441\u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u044b: \u0435\u0451 \u043d\u0435 \u0441\u043b\u0435\u0434\u0443\u0435\u0442 \u043f\u0440\u0438\u043d\u043e\u0441\u0438\u0442\u044c \u0432 \u0436\u0435\u0440\u0442\u0432\u0443 \u0431\u0435\u0441\u043a\u043e\u043d\u0435\u0447\u043d\u043e\u043c\u0443 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044e \u0442\u0435\u043a\u0443\u0449\u0438\u0445 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439.')
change('rest-2', 'en', "The practical implication extends beyond personal willpower. The book discusses company rules allowing recovery after overnight flights or late work. McKeown himself tries a sleeping pod at Google and feels refreshed afterward. The number of users turns out to be far below his expectations. He nevertheless regards the pod's very presence as a signal that sleep deserves priority. Protecting the resource means both allocating time and creating rules that support recovery. For him, the highest priority remains protecting the ability to prioritize, rather than sacrificing it to endless fulfillment of current demands.")
replace('values-2', 'ru', '\u042d\u0442\u043e \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u0440\u0438\u043c\u0435\u0440 \u0432 \u0438\u0437\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0430\u0432\u0442\u043e\u0440\u0430, \u0430 \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0432\u0441\u0435\u0445 \u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0439 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0432 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u043c \u0432\u0440\u0435\u043c\u0435\u043d\u0438. \u0412\u0430\u0436\u043d\u0430 \u0435\u0433\u043e \u0444\u0443\u043d\u043a\u0446\u0438\u044f: \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u044f \u0434\u043e\u043b\u0436\u043d\u0430 \u043f\u043e\u043c\u043e\u0433\u0430\u0442\u044c \u0442\u043e\u0433\u0434\u0430, \u043a\u043e\u0433\u0434\u0430 \u043d\u0435\u043b\u044c\u0437\u044f \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0432\u0441\u0451 \u0441\u0440\u0430\u0437\u0443.', '\u0421\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u044f \u0434\u043e\u043b\u0436\u043d\u0430 \u043f\u043e\u043c\u043e\u0433\u0430\u0442\u044c \u0442\u043e\u0433\u0434\u0430, \u043a\u043e\u0433\u0434\u0430 \u043d\u0435\u043b\u044c\u0437\u044f \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0432\u0441\u0451 \u0441\u0440\u0430\u0437\u0443.')
replace('values-2', 'en', 'This is a historical example as presented by the author, not an assessment of every consequence of the decision in the present. Its function matters: strategy should help when everything cannot be preserved at once.', 'Strategy should help when everything cannot be preserved at once.')
replace('tickets-2', 'ru', '\u041a\u043d\u0438\u0433\u0430 \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 \u0438 \u043e \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u044b\u0445 \u043f\u0440\u0430\u0432\u043e\u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0439, \u0441\u0432\u044f\u0437\u044b\u0432\u0430\u044f \u0435\u0433\u043e \u0441 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u043e\u0439. \u0417\u0434\u0435\u0441\u044c \u044d\u0442\u043e \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0430\u0432\u0442\u043e\u0440\u0441\u043a\u0438\u043c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435\u043c \u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430\u0445, \u0431\u0435\u0437 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0433\u043e \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u043d\u043e\u0439 \u0434\u043e\u043b\u0438 \u0432\u043c\u0435\u0448\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430.', '\u041a\u043d\u0438\u0433\u0430 \u0441\u0432\u044f\u0437\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0443 \u0441\u043e \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435\u043c \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u044b\u0445 \u043f\u0440\u0430\u0432\u043e\u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0439.')
replace('tickets-2', 'en', "The book also reports reduced reoffending, linking it to the program. Here, that remains the author's report of results, without independent establishment of the intervention's causal share.", 'The book links the program with reduced reoffending.')
replace('team', 'ru', '\u042d\u0442\u043e \u043e\u043f\u0438\u0441\u0430\u043d\u043d\u043e\u0435 \u0430\u0432\u0442\u043e\u0440\u043e\u043c \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0435 \u043e\u043f\u044b\u0442\u0430, \u043d\u0435 \u0440\u0430\u043d\u0434\u043e\u043c\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0432\u0441\u0435\u0439 \u0444\u0438\u043b\u043e\u0441\u043e\u0444\u0438\u0438. ', '')
